(6524130, 970349, 50517, '<td valign="top">Beautifully done!</td>', 'Beautifully done!', '2011-09-01 23:53:29.000000', NULL, 1),
(6524134, 970050, 115307, '<td valign="top">Did you blur the sky in editing? Just curious because this image sort of has a tilt shift effect because of the blurring in the sky. Was that intentional? Its a very curious interesting effect!</td>', 'Did you blur the sky in editing? Just curious because this image sort of has a tilt shift effect because of the blurring in the sky. Was that intentional? Its a very curious interesting effect!', '2011-09-01 23:56:16.000000', NULL, 1),
(6524143, 969650, 115307, '<td valign="top">This is a fantastic portrait! So emotive and I love the soft green background. I wish there was a tiny bit more space above her head in the image. But thats it, otherwise this is perfect. 8</td>', 'This is a fantastic portrait! So emotive and I love the soft green background. I wish there was a tiny bit more space above her head in the image. But thats it, otherwise this is perfect. 8', '2011-09-02 00:00:37.000000', NULL, 1),
(6524160, 969684, 66384, '<td valign="top">Yup, that''s a Lake Superior sunset. I saw it every night in July. :) Nicely done. I like the star effect from the small aperture..</td>', 'Yup, that''s a Lake Superior sunset. I saw it every night in July. :) Nicely done. I like the star effect from the small aperture..', '2011-09-02 00:37:52.000000', NULL, 1),
