(6525875, 966542, 136989, '<td valign="top">Lovely.  I would''ve cropped out more of the rocks to be able to bring attention to the lighthouse and that great sky.</td>', 'Lovely.  I would''ve cropped out more of the rocks to be able to bring attention to the lighthouse and that great sky.', '2011-09-03 00:29:07.000000', NULL, 1),
(6525897, 968186, 94235, '<td valign="top">Know how hard it is to capture one of these guys with such clarity. Great job. Well done.</td>', 'Know how hard it is to capture one of these guys with such clarity. Great job. Well done.', '2011-09-03 00:52:12.000000', NULL, 1),
(6525898, 969005, 94235, '<td valign="top">Great capture and timing!</td>', 'Great capture and timing!', '2011-09-03 00:52:48.000000', NULL, 1),
(6525901, 970321, 94235, '<td valign="top">Lovely tones. The processing centers nicely on the couple. Great work.</td>', 'Lovely tones. The processing centers nicely on the couple. Great work.', '2011-09-03 00:54:17.000000', NULL, 1),
(6525905, 970551, 94235, '<td valign="top">Maybe a tad dark in the background but the green leaf in the foreground adds a nice touch to an overall pleasing capture.</td>', 'Maybe a tad dark in the background but the green leaf in the foreground adds a nice touch to an overall pleasing capture.', '2011-09-03 00:56:29.000000', NULL, 1),
(6525906, 968334, 94235, '<td valign="top">Saw lots of these guys on my recent trip to Hong Kong. Didn''t capture one as good as this though. Great work.</td>', 'Saw lots of these guys on my recent trip to Hong Kong. Didn''t capture one as good as this though. Great work.', '2011-09-03 00:57:58.000000', NULL, 1),
(6525908, 969318, 94235, '<td valign="top">Great tones. Something he can proudly look back on in future years.</td>', 'Great tones. Something he can proudly look back on in future years.', '2011-09-03 00:58:55.000000', NULL, 1),
(6525910, 970254, 94235, '<td valign="top">Great timing and processing. Not a big cat fan but love the moment you have captured here!</td>', 'Great timing and processing. Not a big cat fan but love the moment you have captured here!', '2011-09-03 01:00:27.000000', NULL, 1),
(6525911, 970487, 94235, '<td valign="top">Great color. Looks a bit like 3d. Well done.</td>', 'Great color. Looks a bit like 3d. Well done.', '2011-09-03 01:01:40.000000', NULL, 1),
(6525912, 966743, 94235, '<td valign="top">Magic shot. Well framed and captured!</td>', 'Magic shot. Well framed and captured!', '2011-09-03 01:02:11.000000', NULL, 1),
(6525913, 969149, 94235, '<td valign="top">Great stopped action shot. Well captured.</td>', 'Great stopped action shot. Well captured.', '2011-09-03 01:03:27.000000', NULL, 1),
(6525916, 970504, 94235, '<td valign="top">If this were mine I would have it framed and hanging on my wall by now. Great capture and well processed.</td>', 'If this were mine I would have it framed and hanging on my wall by now. Great capture and well processed.', '2011-09-03 01:05:57.000000', NULL, 1),
(6525922, 968544, 60698, '<td valign="top">A masterpiece!</td>', 'A masterpiece!', '2011-09-03 01:17:01.000000', NULL, 1),
(6525924, 969944, 60698, '<td valign="top">I loooove this! It''s so joyful! My favorite in this challenge!</td>', 'I loooove this! It''s so joyful! My favorite in this challenge!', '2011-09-03 01:17:47.000000', NULL, 1),
(6525925, 970418, 113156, '<td valign="top">Lovely photo, the composition is awesome and his posture perfect. 8</td>', 'Lovely photo, the composition is awesome and his posture perfect. 8', '2011-09-03 01:17:49.000000', NULL, 1),
(6525926, 970307, 60698, '<td valign="top">Excellent focus! Perfect image!</td>', 'Excellent focus! Perfect image!', '2011-09-03 01:18:35.000000', NULL, 1),
