INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6526006, 966743, 113019, '<td valign="top">Almost looks like a hoover craft race they way that nearly all of them are level in the air. Great capture.</td>', 'Almost looks like a hoover craft race they way that nearly all of them are level in the air. Great capture.', '2011-09-03 03:32:18.000000', NULL, 1),
(6526007, 970440, 113019, '<td valign="top">About to make the jump to hyper speed.</td>', 'About to make the jump to hyper speed.', '2011-09-03 03:33:29.000000', NULL, 1),
(6526009, 970042, 113019, '<td valign="top">A little soaking wet cutie!! Great capture!</td>', 'A little soaking wet cutie!! Great capture!', '2011-09-03 03:36:49.000000', NULL, 1),
(6526012, 970026, 113019, '<td valign="top">very cool perspective!</td>', 'very cool perspective!', '2011-09-03 03:39:51.000000', NULL, 1),
(6526013, 970519, 113019, '<td valign="top">Love the juxtaposition of the strong structure of the buildings vs. the softness of the clouds.</td>', 'Love the juxtaposition of the strong structure of the buildings vs. the softness of the clouds.', '2011-09-03 03:44:14.000000', NULL, 1),
(6526025, 970558, 113019, '<td valign="top">Beautiful and innovative infant portrait! Best wishes in the competition.</td>', 'Beautiful and innovative infant portrait! Best wishes in the competition.', '2011-09-03 04:18:12.000000', NULL, 1),
(6526026, 969650, 113019, '<td valign="top">Timeless soft and beautiful image!</td>', 'Timeless soft and beautiful image!', '2011-09-03 04:26:52.000000', NULL, 1),
(6526028, 969174, 113019, '<td valign="top">Beautiful and soft image.</td>', 'Beautiful and soft image.', '2011-09-03 04:32:00.000000', NULL, 1),
(6526029, 966166, 113019, '<td valign="top">This is wonderful!! Soft with a bit of sparkle. Best wishes in the competition!</td>', 'This is wonderful!! Soft with a bit of sparkle. Best wishes in the competition!', '2011-09-03 04:37:55.000000', NULL, 1),
(6526130, 968935, 94437, '<td valign="top">The footprints just above the four people seem to end quite suddenly......<br/>great photo.</td>', 'The footprints just above the four people seem to end quite suddenly......great photo.', '2011-09-03 08:31:13.000000', NULL, 1),
(6526219, 970432, 76335, '<td valign="top">Stark, mysterious, exotic.</td>', 'Stark, mysterious, exotic.', '2011-09-03 11:09:52.000000', NULL, 1),
(6526221, 970180, 76335, '<td valign="top">The rich sepia muddies up some of your bubbly bokeh, I think. Nice otherwise.</td>', 'The rich sepia muddies up some of your bubbly bokeh, I think. Nice otherwise.', '2011-09-03 11:10:35.000000', NULL, 1),
(6526222, 966349, 76335, '<td valign="top">Tones are like washed out redscale. Nice.</td>', 'Tones are like washed out redscale. Nice.', '2011-09-03 11:11:02.000000', NULL, 1),
(6526223, 966537, 76335, '<td valign="top">Needs some brighter highlights. But then again, so does New York, perhaps.</td>', 'Needs some brighter highlights. But then again, so does New York, perhaps.', '2011-09-03 11:11:36.000000', NULL, 1),
(6526224, 970399, 76335, '<td valign="top">It''s practically an invitiation. Quirky. I like it.</td>', 'It''s practically an invitiation. Quirky. I like it.', '2011-09-03 11:12:20.000000', NULL, 1),
(6526225, 966430, 76335, '<td valign="top">I like the framing that offsets this somewhat...</td>', 'I like the framing that offsets this somewhat...', '2011-09-03 11:13:24.000000', NULL, 1),
(6526226, 970350, 76335, '<td valign="top">Skin tones are oversaturated. Black and white might have been nice.</td>', 'Skin tones are oversaturated. Black and white might have been nice.', '2011-09-03 11:13:48.000000', NULL, 1),
(6526227, 969005, 83184, '<td valign="top">Wow!</td>', 'Wow!', '2011-09-03 11:14:11.000000', NULL, 1),
(6526228, 970254, 76335, '<td valign="top">What fun. Nicely done.</td>', 'What fun. Nicely done.', '2011-09-03 11:14:33.000000', NULL, 1),
(6526229, 966717, 76335, '<td valign="top">Unexpected and exciting. Different. Great idea.</td>', 'Unexpected and exciting. Different. Great idea.', '2011-09-03 11:14:56.000000', NULL, 1),
(6526230, 970490, 76335, '<td valign="top">Kind of creepy actually. Well executed technically...</td>', 'Kind of creepy actually. Well executed technically...', '2011-09-03 11:15:49.000000', NULL, 1),
(6526232, 970025, 76335, '<td valign="top">I do like the futuristic feel of this. A landscape of machines. The orange tones take it even further.</td>', 'I do like the futuristic feel of this. A landscape of machines. The orange tones take it even further.', '2011-09-03 11:16:30.000000', NULL, 1),
(6526233, 970233, 76335, '<td valign="top">I enjoy the quirky composition with all the anti-focal points -- i.e. there''s lots in the frame but nothing to look at. My only quibble would be the processing which is a trifle overdone.</td>', 'I enjoy the quirky composition with all the anti-focal points -- i.e. there''s lots in the frame but nothing to look at. My only quibble would be the processing which is a trifle overdone.', '2011-09-03 11:18:06.000000', NULL, 1),
(6526235, 970500, 76335, '<td valign="top">A great find, well framed.</td>', 'A great find, well framed.', '2011-09-03 11:18:35.000000', NULL, 1),
(6526236, 970439, 76335, '<td valign="top">The yellow is ominous. Very sci-fi.</td>', 'The yellow is ominous. Very sci-fi.', '2011-09-03 11:19:00.000000', NULL, 1),
(6526239, 970496, 47470, '<td valign="top">I love the pose of the bird and how it is highlighted with the reflection on the water.  You could have cropped closer on that part to emphasize how beautiful that part is.  I would have preferred a shallower depth of field to blur out the background.</td>', 'I love the pose of the bird and how it is highlighted with the reflection on the water.  You could have cropped closer on that part to emphasize how beautiful that part is.  I would have preferred a shallower depth of field to blur out the background.', '2011-09-03 11:21:18.000000', NULL, 1),
(6526241, 966328, 76335, '<td valign="top">Very effective point of view here. Nicely composed.</td>', 'Very effective point of view here. Nicely composed.', '2011-09-03 11:22:23.000000', NULL, 1),
