(6527645, 970336, 60698, '<td valign="top">Nice DOF, color and composition! Great capture!</td>', 'Nice DOF, color and composition! Great capture!', '2011-09-04 17:48:21.000000', NULL, 1),
(6527646, 969508, 58634, '<td valign="top">The composition of the image is just too cluttered.. The unfocused leaves in the front are distracting and don''t add any value to the overall image. The lighting is pretty harsh on the left side of the wall but the butterfly isn''t overblown with higlights which is good. It''s cute that you were able to hold the butterly on your finger (or whoever''s holding it lol).. I think this would''ve worked better had you cropped everything  and just kept the butterfly close up.</td>', 'The composition of the image is just too cluttered.. The unfocused leaves in the front are distracting and don''t add any value to the overall image. The lighting is pretty harsh on the left side of the wall but the butterfly isn''t overblown with higlights which is good. It''s cute that you were able to hold the butterly on your finger (or whoever''s holding it lol).. I think this would''ve worked better had you cropped everything  and just kept the butterfly close up.', '2011-09-04 17:48:51.000000', NULL, 1),
(6527648, 970042, 58634, '<td valign="top">This is just so silly! Great action going on in here.. The focusing works really well with some of the droplets being in focus, as well as the background being blurry. Works well in black and white also. I like this a lot!</td>', 'This is just so silly! Great action going on in here.. The focusing works really well with some of the droplets being in focus, as well as the background being blurry. Works well in black and white also. I like this a lot!', '2011-09-04 17:49:47.000000', NULL, 1),
(6527650, 970092, 60698, '<td valign="top">Awesome! Clouds and dark purplish color are a lovely complement to the perfectly captured lightning! I like the simplicity, also!</td>', 'Awesome! Clouds and dark purplish color are a lovely complement to the perfectly captured lightning! I like the simplicity, also!', '2011-09-04 17:50:56.000000', NULL, 1),
(6527651, 969190, 60698, '<td valign="top">Wow! What a capture!</td>', 'Wow! What a capture!', '2011-09-04 17:51:21.000000', NULL, 1),
