INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6527685, 970396, 58634, '<td valign="top">Lovely location for a fun photoshoot. The model fits right in with the environment around her and everything looks gorgeous.</td>', 'Lovely location for a fun photoshoot. The model fits right in with the environment around her and everything looks gorgeous.', '2011-09-04 18:22:42.000000', NULL, 1),
(6527686, 970418, 58634, '<td valign="top">Simple and yet meaningful.</td>', 'Simple and yet meaningful.', '2011-09-04 18:23:28.000000', NULL, 1),
(6527687, 966298, 58634, '<td valign="top">The image seems overexposed which makes it pretty hard to even notice the rain actually falling. Your title is very fitting of what that bird is probably thinking though!!</td>', 'The image seems overexposed which makes it pretty hard to even notice the rain actually falling. Your title is very fitting of what that bird is probably thinking though!!', '2011-09-04 18:24:21.000000', NULL, 1),
(6527688, 965459, 58634, '<td valign="top">Almost looks like it''s doing yoga or something of the sort. I am amused.</td>', 'Almost looks like it''s doing yoga or something of the sort. I am amused.', '2011-09-04 18:24:48.000000', NULL, 1),
(6527690, 970557, 58634, '<td valign="top">Interesting concept, for sure. I''m not too crazy about the centered composition though..</td>', 'Interesting concept, for sure. I''m not too crazy about the centered composition though..', '2011-09-04 18:25:41.000000', NULL, 1),
(6527691, 970448, 58634, '<td valign="top">Very dreamy.. makes me wonder why they''re standing there.</td>', 'Very dreamy.. makes me wonder why they''re standing there.', '2011-09-04 18:26:10.000000', NULL, 1),
(6527692, 969174, 58634, '<td valign="top">My first thoughts upon opening this were "whoah", but I think that was the shock factor since I wasn''t quote expecting this, lol. <br/> <br/>I enjoy the bright lighting and the black and white tones as it emphasizes all the right things in this picture.</td>', 'My first thoughts upon opening this were "whoah", but I think that was the shock factor since I wasn''t quote expecting this, lol.  I enjoy the bright lighting and the black and white tones as it emphasizes all the right things in this picture.', '2011-09-04 18:28:36.000000', NULL, 1),
