(6531405, 970124, 109227, '<td valign="top">Nicely composed.  The sunlight looks a little harsh on the side of the boat, but still a very nice image. (voted earlier)</td>', 'Nicely composed.  The sunlight looks a little harsh on the side of the boat, but still a very nice image. (voted earlier)', '2011-09-07 10:02:20.000000', NULL, 1),
(6531406, 966298, 59737, '<td valign="top">the feeder really overpowers this shot, the bird is so small in comparison that it is a little bit lost.  I don''t know if a tighter crop showing more of the bird and the rain would have worked better.</td>', 'the feeder really overpowers this shot, the bird is so small in comparison that it is a little bit lost.  I don''t know if a tighter crop showing more of the bird and the rain would have worked better.', '2011-09-07 10:03:34.000000', NULL, 1),
(6531407, 970145, 109227, '<td valign="top">I''ve been to Medicine Bow several times; it is a beautiful area and you have captured a very nice image of it.  I am not sure about the square crop as I think it loses some of the vastness and makes the peak of the mountain dead center.  (voted earlier)</td>', 'I''ve been to Medicine Bow several times; it is a beautiful area and you have captured a very nice image of it.  I am not sure about the square crop as I think it loses some of the vastness and makes the peak of the mountain dead center.  (voted earlier)', '2011-09-07 10:04:54.000000', NULL, 1),
(6531409, 970574, 109227, '<td valign="top">Looks like something from a movie.  Nice light and I like the reflection. (voted earlier)</td>', 'Looks like something from a movie.  Nice light and I like the reflection. (voted earlier)', '2011-09-07 10:06:18.000000', NULL, 1),
(6531410, 970226, 109227, '<td valign="top">great find and beautiful colors; composition wise,he seems a little too far right; move in a little to better catch your attention. (voted earlier)</td>', 'great find and beautiful colors; composition wise,he seems a little too far right; move in a little to better catch your attention. (voted earlier)', '2011-09-07 10:06:40.000000', NULL, 1),
