(6533184, 968544, 39184, '<td valign="top">Congratulations on pulling off the whole scene and for the blue.  I appreciate you posting the story of the process...good reading.</td>', 'Congratulations on pulling off the whole scene and for the blue.  I appreciate you posting the story of the process...good reading.', '2011-09-08 10:27:55.000000', NULL, 0),
(6533192, 970092, 39184, '<td valign="top">Congratulations on such a high placement.  12 seconds?!?  Wow, that''s a steady set of hands!</td>', 'Congratulations on such a high placement.  12 seconds?!?  Wow, that''s a steady set of hands!', '2011-09-08 10:38:52.000000', NULL, 0),
